# RFC 8032 vectors + independent cross-checks.
# 17 vectors: 3 official RFC 8032 7.1 vectors, 1 32-byte message vector and
# 13 generated by a pure-python reference implementation.

while IFS='|' read -r _name _seed _pub _msghex _sig; do
	case "$_name" in ''|'#'*) continue ;; esac

	_mf="$_TMP/$_name.bin"
	if [ "$_msghex" = "-" ]; then
		: >"$_mf"
	else
		printf '%s' "$_msghex" | xxd -r -p >"$_mf"
	fi

	assert_eq "$(ed25519_pub_hex "$_seed")" "$_pub" "pub  $_name"

	_sig_got="$(ed25519_sign_hex "$_seed" "$_mf")"
	assert_eq "$_sig_got" "$_sig" "sign $_name"

	ed25519_verify_hex "$_pub" "$_mf" "$_sig" 2>/dev/null
	assert_ok "verify $_name"

	# tampered signature (last byte changed) must be rejected
	_last="$(printf '%s' "$_sig" | cut -c128)"
	case "$_last" in 0) _rep=1 ;; *) _rep=0 ;; esac
	_tsig="$(printf '%s' "$_sig" | cut -c1-127)$_rep"
	ed25519_verify_hex "$_pub" "$_mf" "$_tsig" 2>/dev/null
	assert_fail "verify tampered sig $_name"

	# tampered message must be rejected
	printf 'x' >>"$_mf"
	ed25519_verify_hex "$_pub" "$_mf" "$_sig" 2>/dev/null
	assert_fail "verify tampered msg $_name"
done <test/vectors/rfc8032.txt

# same message signed with a different key must not match the first public key
printf 'hush' >"$_TMP/m1"
_p1="$(ed25519_pub_hex 9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60)"
_s1="$(ed25519_sign_hex 9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60 "$_TMP/m1")"
_p2="$(ed25519_pub_hex 4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb)"
assert_ne "$_p1" "$_p2" "distinct keys produce distinct pubkeys"
ed25519_verify_hex "$_p2" "$_TMP/m1" "$_s1" 2>/dev/null
assert_fail "verify with wrong pubkey"
